SELECT TASK_ID as taskId, TASK_NAME as taskName, TASK_TYPE as taskType, EXPORT_FORMAT as exportFormat, STATUS as status, PROGRESS_PERCENT as progressPercent, TOTAL_RECORDS as totalRecords, PROCESSED_RECORDS as processedRecords, START_TIME as startTime, END_TIME as endTime, DURATION as duration, FILE_NAME as fileName, FILE_SIZE as fileSize, DOWNLOAD_COUNT as downloadCount, ERROR_MESSAGE as errorMessage, CREATE_TIME as createTime FROM T_EXPORT_TASK WHERE CREATOR = #{param.userId} AND IS_DELETED = 0
AND STATUS = #{param.status}
ORDER BY CREATE_TIME DESC OFFSET #{param.offset} ROWS FETCH NEXT #{param.pageSize} ROWS ONLY

SELECT COUNT(1)
FROM T_EXPORT_TASK
WHERE CREATOR = #{param.userId}
  AND IS_DELETED = 0

    AND STATUS = #{param.status}

SELECT TASK_ID as taskId, TASK_NAME as taskName, TASK_TYPE as taskType, EXPORT_FORMAT as exportFormat, STATUS as status, PROGRESS_PERCENT as progressPercent, TOTAL_RECORDS as totalRecords, PROCESSED_RECORDS as processedRecords, START_TIME as startTime, END_TIME as endTime, DURATION as duration, FILE_NAME as fileName, FILE_SIZE as fileSize, DOWNLOAD_COUNT as downloadCount, CREATOR as creator, ERROR_MESSAGE as errorMessage, CREATE_TIME as createTime FROM T_EXPORT_TASK WHERE IS_DELETED = 0
AND STATUS = #{param.status}
AND TASK_TYPE = #{param.taskType}
ORDER BY CREATE_TIME DESC OFFSET #{param.offset} ROWS FETCH NEXT #{param.pageSize} ROWS ONLY

SELECT COUNT(1)
FROM T_EXPORT_TASK
WHERE IS_DELETED = 0

    AND STATUS = #{param.status}


    AND TASK_TYPE = #{param.taskType}

SELECT COUNT(1)
FROM T_FINANCIAL_REPORT fr
WHERE fr.IS_DELETED = 0

    AND fr.REPORT_TYPE = #{param.reportType}


    AND fr.REPORT_PERIOD = #{param.reportPeriod}


    AND fr.BOOK_ID = CAST(#{param.bookId} AS NUMBER)

SELECT fr.REPORT_ID as reportId, fr.REPORT_NAME as reportName, fr.REPORT_TYPE as reportType, fr.REPORT_PERIOD as reportPeriod, fr.REPORT_DATE as reportDate, fr.TOTAL_ASSETS as totalAssets, fr.TOTAL_LIABILITIES as totalLiabilities, fr.TOTAL_EQUITY as totalEquity, fr.NET_PROFIT as netProfit, fr.OPERATING_REVENUE as operatingRevenue, fr.OPERATING_COSTS as operatingCosts, fr.REMARK as remark, fr.CREATE_TIME as createTime, fr.CREATOR as creator FROM T_FINANCIAL_REPORT fr WHERE fr.IS_DELETED = 0
AND fr.REPORT_TYPE = #{param.reportType}
AND fr.REPORT_PERIOD = #{param.reportPeriod}
AND fr.BOOK_ID = CAST(#{param.bookId} AS NUMBER)
ORDER BY fr.REPORT_DATE DESC, fr.REPORT_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY
